create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,email text,phone text,avatar_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.sale_offers(id uuid primary key default gen_random_uuid(),title text not null,description text,property_type text,price numeric,location text,address text,area numeric,bedrooms integer,bathrooms integer,floor integer,furnished boolean default false,status text not null default 'active',created_by uuid references public.profiles(id),created_at timestamptz default now(),updated_at timestamptz default now());
create table public.rental_offers(like public.sale_offers including all);
create table public.property_images(id uuid primary key default gen_random_uuid(),property_type text not null,property_id uuid not null,image_path text not null,image_url text,sort_order integer default 0,created_at timestamptz default now());
create table public.requests(id uuid primary key default gen_random_uuid(),customer_name text not null,phone text not null,request_type text,property_type text,location text,budget numeric,area numeric,bedrooms integer,bathrooms integer,description text,status text default 'new',notes text,created_by uuid references public.profiles(id),created_at timestamptz default now(),updated_at timestamptz default now());
create table public.app_settings(id uuid primary key default gen_random_uuid(),app_name text default 'القِرش | Alqirsh',contact_phone text default '01090886364',about_text text,logo_url text,updated_at timestamptz default now());
